  if ((docRaw && !docId) || (idRaw && !productId) || (docId && productId && docId !== productId)) {
    return { ok: false, status: 409, message: 'Identifier produk laboratorium tidak cocok dengan katalog backend.' };
  }
  const numericId = docId || productId;
  if (!numericId) {
    return { ok: false, status: 409, message: 'Produk laboratorium wajib membawa identifier katalog backend.' };
  }
  const submittedTitle = sessionOwnershipCheckoutCleanText(requestedProductTitle || row.product_title || row.title || '', 180);
  const productTitle = idRaw && submittedTitle === 'Produk Laboratorium ' + idRaw
