  if (!productTitle) return { ok: false, status: 409, message: 'Nama produk laboratorium tidak valid.' };
  const expectedTitleHash = DIRAC_LABORATORY_CHECKOUT_CATALOG_V443.titleSha256[numericId - 1] || '';
