  if (!expectedTitleHash || actualTitleHash !== expectedTitleHash) {
    return { ok: false, status: 409, message: 'Identitas produk laboratorium tidak cocok dengan katalog backend.' };
  }
  const price = Number(DIRAC_LABORATORY_CHECKOUT_CATALOG_V443.prices[numericId - 1] || 0);
  if (!Number.isSafeInteger(price) || price <= 0) {
    return { ok: false, status: 409, message: 'Harga produk laboratorium belum dapat dikunci backend.' };
  }
  const sku = numericId <= 650
