    keyId: envelope.keyId,
    publicKeyJwk: envelope.publicKeyJwk,
    version: DIRAC_PASSKEY_DEVICE_BINDING_VERSION,
    algorithm: DIRAC_PASSKEY_DEVICE_BINDING_ALGORITHM,
