    if (copy.payment_status === 'paid' && paid && copy.currency === paid.currency
        && midtransStrictMoneyV350(paid.amount) !== null
        && midtransStrictMoneyV350(paid.amount) === midtransStrictMoneyV350(copy.total)) {
      copy.gateway_reference = paid.gatewayReference;
      copy.payment_transaction_id = paid.transactionId;
      copy.payment_provider = 'midtrans';
      copy.payment_return_verified = true;
      copy.payment_confirmed_at = paid.confirmedAt;
    }
    if (copy.payment_status === 'paid' && method && copy.currency === method.currency
        && midtransStrictMoneyV350(method.amount) !== null
        && midtransStrictMoneyV350(method.amount) === midtransStrictMoneyV350(copy.total)
        && (!copy.payment_method || /^(belum dipilih|tidak tersedia|-)$/i.test(String(copy.payment_method).trim()))) {
      copy.payment_method = method.label;
      copy.payment_method_source = 'verified_gateway';
    }

    if (canPay && tx && midtransTrustedPaymentUrlV352(tx.payment_url)
        && midtransStrictMoneyV350(tx.amount) === midtransStrictMoneyV350(copy.total)) {
      copy.payment_url = String(tx.payment_url);
      copy.payment_transaction_id = tx.id || null;
      copy.gateway_reference = tx.gateway_reference || null;
      copy.payment_provider = tx.gateway_name || null;
      copy.payment_gateway_configured = gatewayConfigured;
      copy.can_pay = diracUniversalPesananOrderCanPay(copy);
      copy.payment_message = 'Payment sudah tersedia. Tekan tombol untuk melanjutkan pembayaran.';
      delete copy.order_database;
      return [copy];
    }

    copy.payment_url = copy.payment_url || null;
    copy.payment_gateway_configured = gatewayConfigured;
    copy.can_pay = canPay;
    copy.payment_message = canPay
      ? 'Tekan Bayar Sekarang untuk membayar sesuai jumlah tagihan Anda.'
      : (gatewayConfigured
        ? 'Invoice ini belum eligible untuk payment otomatis.'
        : 'Layanan pembayaran belum tersedia.');
    delete copy.order_database;
    return [copy];
